"""Lesson-only UI regression suite. Model output is a controlled fixture."""
from playwright.sync_api import sync_playwright,expect
from browser_helpers import *
import json
checks=[];errors=[]
def passed(name):checks.append(name);print(name,flush=True)
with sync_playwright() as p:
 b=launch(p);c=mobile(b,'window.setupDelay=650;');page=c.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.goto(BASE)
 expect(page.locator('h1')).to_contain_text('A little AI.');expect(page.locator('[aria-label="Qwen download progress"]')).to_be_visible();assert page.evaluate('window.loads')==1
 page.screenshot(path='/workspace/scratch/lingrove-simple-setup.png');page.locator('[data-language="zh"]').click();expect(page.locator('#lesson-topic')).to_be_visible();assert page.evaluate('window.checkedReady');assert page.locator('nav button').count()==2
 passed('Automatic setup passes readiness and goes directly to language choice')
 page.locator('#lesson-topic').fill('A conversation about ordering tea');page.locator('.customize summary').click();page.locator('#lesson-level').select_option('B1');page.locator('#lesson-length').select_option('6');page.locator('#lesson-format').select_option('dialogue');page.locator('#lesson-focus').fill('please and thank you');page.locator('#lesson-instructions').fill('Make it suitable for an adult beginner.');page.screenshot(path='/workspace/scratch/lingrove-simple-create.png');page.locator('#generate-button').click()
 expect(page.locator('.lesson-heading h1')).to_have_text('一杯茶');assert page.locator('.lesson-line').count()==6
 request=page.evaluate('lastRequest');assert 'Mandarin Chinese' in request['messages'][0]['content'] and 'B1' in request['messages'][0]['content'] and 'dialogue' in request['messages'][0]['content'];assert 'please and thank you' in request['messages'][1]['content'];assert json.loads(request['response_format']['schema'])['properties']['lines']['minItems']==6
 stored=page.evaluate("JSON.parse(localStorage.getItem('lingrove-lessons-v2'))");assert len(stored['lessons'])==1;assert stored['lessons'][0]['lines'][0][2];assert stored['lessons'][0]['language']=='zh';passed('All customization reaches the model; bilingual lesson auto-saves with pinyin')
 assert not page.evaluate('document.documentElement.scrollWidth>innerWidth');page.screenshot(path='/workspace/scratch/lingrove-simple-reader.png',full_page=True)
 page.locator('#show-translations').uncheck();assert not page.locator('.translation').first.evaluate('(e)=>e.open');page.locator('#show-translations').check();page.locator('#show-pinyin').uncheck();assert page.locator('.pinyin').count()==0;page.locator('#show-pinyin').check();passed('Reader toggles and phone layout work')
 more(page,'edit');page.locator('#edit-title').fill('Tea with a friend');page.locator('[data-edit-zh="0"]').fill('请给我一杯茶。');page.get_by_role('button',name='Save changes').click();expect(page.locator('.lesson-heading .subtitle')).to_have_text('Tea with a friend');expect(page.locator('.pinyin').first).to_contain_text('Qǐng');page.reload();expect(page.locator('.lesson-heading .subtitle')).to_have_text('Tea with a friend');passed('Bilingual editing persists and updates pronunciation')
 page.locator('.reader-actions .menu summary').click()
 with page.expect_download() as download:page.locator('[data-action="export-lesson"]').click()
 exported=json.load(open(download.value.path()));assert exported['lessons'][0]['title']=='Tea with a friend';passed('Lesson backup contains the saved bilingual data')
 page.locator('nav [data-nav="saved"]').click();expect(page.locator('.saved-lesson')).to_have_count(1);page.locator('#saved-search').fill('missing');expect(page.locator('.saved-lesson')).to_have_count(0);page.locator('#saved-search').fill('Tea');expect(page.locator('.saved-lesson')).to_have_count(1)
 imported={**exported['lessons'][0],'id':'import-test','title':'<img src=x onerror="window.injected=1">','zhTitle':'导入的课','spec':{'topic':'A different subject'}};page.locator('#backup-file').set_input_files({'name':'backup.json','mimeType':'application/json','buffer':json.dumps({'lessons':[imported]}).encode()});expect(page.locator('.saved-lesson')).to_have_count(1);page.locator('#saved-search').fill('');expect(page.locator('.saved-lesson')).to_have_count(2);page.locator('[data-open="import-test"]').click();assert not page.evaluate('window.injected||false');expect(page.locator('.lesson-heading .subtitle')).to_contain_text('<img');passed('Saved search, backup import and safe text rendering work')
 page.on('dialog',lambda d:d.accept());more(page,'delete');expect(page.locator('.saved-lesson')).to_have_count(1);page.reload();expect(page.locator('.saved-lesson')).to_have_count(1);passed('Deleting one lesson preserves the other across reload')
 c.close()
 # First-visit setup failures and cancellation must always leave a retry.
 c=mobile(b,"window.setupError='Download unavailable';");q=c.new_page();q.goto(BASE);expect(q.locator('#setup-progress')).to_contain_text('Download unavailable');q.evaluate('window.setupError=null');q.locator('[data-action="retry-setup"]').click();expect(q.locator('[data-language="en"]')).to_be_visible();c.close()
 c=mobile(b,'window.setupDelay=4000;');q=c.new_page();q.goto(BASE);q.locator('[data-action="cancel-setup"]').click();expect(q.locator('#setup-progress')).to_contain_text('Download paused');q.evaluate('window.setupDelay=10');q.locator('[data-action="retry-setup"]').click();expect(q.locator('[data-language="en"]')).to_be_visible();passed('Failed and cancelled automatic downloads recover with one retry');c.close()
 # Failed and stalled model jobs must not trap the form.
 c=mobile(b);q=c.new_page();start(q);q.evaluate("window.modelError='Worker failed';");q.locator('#lesson-topic').fill('Tea');q.locator('#generate-button').click();expect(q.locator('#generation-status')).to_contain_text('Worker failed');expect(q.locator('#generate-button')).to_be_enabled();q.evaluate('window.modelError=null;window.stall=true');q.locator('#generate-button').click();q.wait_for_function("document.querySelector('#generation-status strong')?.textContent==='Writing your lesson'");q.locator('[data-action="stop-generation"]').click();expect(q.locator('#generate-button')).to_be_enabled(timeout=6000);expect(q.locator('#generation-status')).to_contain_text('stopped');q.evaluate('window.stall=false');q.locator('#generate-button').click();expect(q.locator('.lesson-heading h1')).to_have_text('A cup of tea');passed('Generation errors and Stop recover; retry saves the next lesson');c.close()
 # Storage blocked: content is retained and explicitly marked unsaved.
 c=mobile(b);q=c.new_page();start(q);q.evaluate("()=>{Storage.prototype.setItem=function(){throw new Error('QuotaExceededError')}}");generate(q);expect(q.locator('.save-status')).to_have_text('Not saved yet');expect(q.locator('[data-action="save-again"]')).to_be_visible();more(q,'export-lesson');passed('Storage failure retains the lesson and offers a downloadable backup');c.close()
 # Legacy generated lessons migrate; built-ins do not appear.
 legacy={'language':'en','custom':[{'id':'legacy','title':'My old lesson','lines':[['Hello.','你好。','Nǐ hǎo.']]}],'words':[{'text':'hello'}]}
 script="if(!localStorage.getItem('lingrove-v1'))localStorage.setItem('lingrove-v1',"+json.dumps(json.dumps(legacy))+');'
 c=mobile(b,script);q=c.new_page();q.goto(BASE+'#/saved');expect(q.locator('.saved-lesson')).to_have_count(1);q.locator('[data-open="legacy"]').click();expect(q.locator('.lesson-heading h1')).to_have_text('My old lesson');assert json.loads(q.evaluate("localStorage.getItem('lingrove-v1')"))==legacy;passed('Existing custom lessons migrate without deleting legacy learning data');c.close()
 assert not errors,errors
 print(json.dumps({'passed':len(checks),'errors':errors}));b.close()
